"""Source-gated diagonal pedestrian construction and original-frame readback.

The packet is a measured site proposal. Its authority records must be checked
against original documents; a CARLA traffic light alone cannot authorize a
pedestrian diagonal crossing. No legal outcome is inferred here.
"""
from __future__ import annotations

import hashlib
import math
from pathlib import Path


def _point(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("measured map-XY point required")
    point = tuple(float(n) for n in value)
    if not all(math.isfinite(n) for n in point):
        raise ValueError("nonfinite point")
    return point


def _source(packet, name, root=None):
    item = packet.get("sources", {}).get(name)
    if not isinstance(item, dict) or not item.get("path") or not item.get("sha256"):
        raise ValueError(f"missing source: {name}")
    file = Path(item["path"])
    if root is not None:
        base = Path(root).resolve()
        original = base / file
        file = original.resolve()
        if not file.is_relative_to(base) or original.is_symlink():
            raise ValueError(f"source escapes attempt: {name}")
    if not file.is_file() or hashlib.sha256(file.read_bytes()).hexdigest() != item["sha256"]:
        raise ValueError(f"source hash mismatch: {name}")
    return item


def validate_site(packet, root=None):
    for name in ("map", "corner_survey", "authorization", "device_inventory", "exception_review"):
        _source(packet, name, root)
    if packet.get("coordinate_frame") != "map_xy_m":
        raise ValueError("unsupported coordinate frame")
    corners = [_point(p) for p in packet["corners_clockwise"]]
    if len(corners) != 4 or len(set(corners)) != 4:
        raise ValueError("four surveyed, distinct intersection corners required")
    start, destination = corners[0], corners[2]
    if math.dist(start, destination) < 3:
        raise ValueError("diagonal endpoints too close")
    route = [_point(p) for p in packet["pedestrian_route"]]
    if len(route) < 3 or math.dist(route[0], start) > 0.5 or math.dist(route[-1], destination) > 0.5:
        raise ValueError("route must connect opposite surveyed corners")
    if not all(math.dist(a, b) > 0.1 for a, b in zip(route, route[1:])):
        raise ValueError("zero-length route segment")
    device = packet["governing_device"]
    for name in ("id", "authority_record_id", "instruction_record_id", "placement_record_id"):
        if not device.get(name):
            raise ValueError(f"missing governing device provenance: {name}")
    if device.get("governs") != "pedestrian_diagonal" or device.get("diagonal_authorized") is not True:
        raise ValueError("official pedestrian diagonal authorization unestablished")
    if device["id"] not in packet.get("observed_device_ids", []):
        raise ValueError("governing device not inventoried on site")
    if packet.get("exception_484b_290_review") not in {"not_applicable_source_review", "unresolved"}:
        raise ValueError("exception review missing")
    return {"start_xy": start, "destination_xy": destination,
            "route_xy": route, "device_id": device["id"],
            "source_sha256": {name: packet["sources"][name]["sha256"] for name in
                              ("map", "corner_survey", "authorization", "device_inventory", "exception_review")},
            "exception_484b_290_review": packet["exception_484b_290_review"]}


def spawn_walker(world, packet, *, carla_module=None):
    plan = validate_site(packet)
    blueprint_id = packet.get("walker_blueprint_id")
    if not isinstance(blueprint_id, str) or not blueprint_id.startswith("walker.pedestrian."):
        raise ValueError("walker blueprint ID required")
    if carla_module is None:
        import carla as carla_module
    start = plan["start_xy"]
    transform = carla_module.Transform(carla_module.Location(x=start[0], y=start[1], z=float(packet["spawn_z_m"])))
    blueprint = world.get_blueprint_library().find(blueprint_id)
    actor = world.try_spawn_actor(blueprint, transform)
    if actor is None:
        raise RuntimeError("walker spawn failed")
    try:
        if actor.type_id != blueprint_id:
            raise ValueError("walker blueprint readback mismatch")
        location = actor.get_location()
        if math.hypot(location.x - start[0], location.y - start[1]) > 1.0:
            raise ValueError("walker start readback mismatch")
        return actor, plan
    except Exception:
        actor.destroy()
        raise


def advance_walker(actor, plan, route_index, speed_mps, *, carla_module=None):
    if carla_module is None:
        import carla as carla_module
    if not 1 <= route_index < len(plan["route_xy"]):
        raise ValueError("route index out of range")
    if not math.isfinite(float(speed_mps)) or float(speed_mps) <= 0:
        raise ValueError("positive speed required")
    target = plan["route_xy"][route_index]
    location = actor.get_location()
    distance = math.hypot(target[0] - location.x, target[1] - location.y)
    if distance < 0.35 and route_index + 1 < len(plan["route_xy"]):
        route_index += 1
        target = plan["route_xy"][route_index]
        distance = math.hypot(target[0] - location.x, target[1] - location.y)
    if distance < 0.35:
        actor.apply_control(carla_module.WalkerControl(direction=carla_module.Vector3D(0, 0, 0), speed=0))
        return route_index
    direction = carla_module.Vector3D((target[0] - location.x) / distance, (target[1] - location.y) / distance, 0)
    actor.apply_control(carla_module.WalkerControl(direction=direction, speed=float(speed_mps)))
    return route_index

"""Stream and independently decode four original Native camera sources.

The small profile override is only for CPU tests. Production uses the pinned
worker capture dimensions; a decoded pixel stream never proves walker visibility.
"""
from __future__ import annotations

import hashlib
import json
import subprocess
from pathlib import Path

CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")
PROFILE = {"overview": (1920, 1080), "approach": (1280, 720),
           "reference_corner": (1280, 720), "driver_reference": (1280, 720)}


def _sha_file(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def _probe(path):
    output = subprocess.check_output([
        "ffprobe", "-v", "error", "-select_streams", "v:0",
        "-show_entries", "stream=width,height,r_frame_rate,codec_name",
        "-of", "json", str(path)], text=True)
    streams = json.loads(output).get("streams", [])
    if len(streams) != 1:
        raise ValueError("one original video stream required")
    return streams[0]


class FourCameraRecorder:
    """Encode one synchronized BGRA image per original world tick."""

    def __init__(self, attempt, profile=None, *, diagnostic=False, factory=subprocess.Popen):
        self.attempt = Path(attempt).resolve()
        if not self.attempt.is_dir():
            raise ValueError("existing attempt directory required")
        self.profile = dict(PROFILE if profile is None else profile)
        if set(self.profile) != set(CAMERAS) or (not diagnostic and self.profile != PROFILE):
            raise ValueError("four pinned camera dimensions required")
        self.processes = {}
        self.paths = {}
        self.count = 0
        self.previous_frame = None
        self.closed = False
        try:
            for name in CAMERAS:
                width, height = self.profile[name]
                if not isinstance(width, int) or not isinstance(height, int) or width < 1 or height < 1:
                    raise ValueError("camera dimensions invalid")
                path = self.attempt / (name + ".mkv")
                if path.exists():
                    raise ValueError("original camera output already exists")
                command = ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error", "-n",
                           "-f", "rawvideo", "-pixel_format", "bgra", "-video_size",
                           f"{width}x{height}", "-framerate", "20", "-i", "pipe:0", "-an",
                           "-c:v", "ffv1", "-pix_fmt", "bgra", str(path)]
                self.paths[name] = path
                self.processes[name] = factory(command, stdin=subprocess.PIPE,
                                               stderr=subprocess.PIPE)
        except BaseException:
            self.close(require_success=False)
            raise

    def append(self, frame, images):
        if self.closed:
            raise ValueError("camera recorder closed")
        if type(frame) is not int or (self.previous_frame is not None and frame != self.previous_frame + 1):
            raise ValueError("camera original frame discontinuity")
        if not isinstance(images, dict) or set(images) != set(CAMERAS):
            raise ValueError("four original camera images required")
        # Validate all views before writing any one view for this tick.
        for name in CAMERAS:
            image = images[name]
            width, height = self.profile[name]
            if (getattr(image, "frame", None) != frame or
                    getattr(image, "width", None) != width or
                    getattr(image, "height", None) != height or
                    not isinstance(getattr(image, "raw_data", None), bytes) or
                    len(image.raw_data) != width * height * 4):
                raise ValueError(name + " original BGRA frame or dimensions differ")
        for name in CAMERAS:
            data = images[name].raw_data
            written = self.processes[name].stdin.write(data)
            if written != len(data):
                raise ValueError(name + " original camera frame incomplete")
        self.previous_frame = frame
        self.count += 1

    def close(self, *, require_success=True):
        if self.closed:
            return
        self.closed = True
        errors = []
        for name, process in self.processes.items():
            try:
                if process.stdin and not process.stdin.closed:
                    process.stdin.close()
                code = process.wait(timeout=180)
                if code and require_success:
                    errors.append(name + " FFV1 encoder failed")
            except BaseException as exc:
                process.kill()
                process.wait()
                errors.append(name + " encoder failed: " + str(exc))
            finally:
                if process.stderr:
                    process.stderr.close()
        if errors and require_success:
            raise ValueError("; ".join(errors))

    def source_receipt(self):
        if not self.closed or self.count <= 0:
            raise ValueError("closed nonempty original camera recorder required")
        return {name: {"path": path.name,
                       "sha256": _sha_file(path),
                       "frames": self.count}
                for name, path in self.paths.items()}


def audit_original_media(attempt, sources, expected_frames, *, profile=None,
                         diagnostic=False):
    """Decode every pixel of every frame and reject short/stale source videos."""
    attempt = Path(attempt).resolve()
    dimensions = dict(PROFILE if profile is None else profile)
    if set(sources) != set(CAMERAS) or set(dimensions) != set(CAMERAS):
        raise ValueError("four original camera sources required")
    if not diagnostic and dimensions != PROFILE:
        raise ValueError("production camera profile differs")
    if type(expected_frames) is not int or expected_frames < 1:
        raise ValueError("expected original frame count required")
    result = {}
    for name in CAMERAS:
        ref = sources[name]
        if not isinstance(ref, dict) or not isinstance(ref.get("path"), str):
            raise ValueError(name + " camera source reference missing")
        original = attempt / ref["path"]
        path = original.resolve()
        if not path.is_relative_to(attempt) or original.is_symlink() or not path.is_file():
            raise ValueError(name + " camera source missing or escapes attempt")
        before = _sha_file(path)
        if before != ref.get("sha256") or ref.get("frames") != expected_frames:
            raise ValueError(name + " original camera source hash/count mismatch")
        metadata = _probe(path)
        width, height = dimensions[name]
        if ([metadata.get("width"), metadata.get("height")] != [width, height] or
                metadata.get("r_frame_rate") != "20/1" or
                metadata.get("codec_name") != "ffv1"):
            raise ValueError(name + " original camera codec, dimensions or rate differ")
        command = ["ffmpeg", "-nostdin", "-hide_banner", "-loglevel", "error",
                   "-i", str(path), "-vsync", "0", "-f", "rawvideo", "-pix_fmt",
                   "rgb24", "pipe:1"]
        process = subprocess.Popen(command, stdout=subprocess.PIPE,
                                   stderr=subprocess.PIPE)
        digest = hashlib.sha256()
        count = 0
        frame_bytes = width * height * 3
        try:
            while True:
                block = process.stdout.read(frame_bytes)
                if not block:
                    break
                if len(block) != frame_bytes or count >= expected_frames:
                    raise ValueError(name + " truncated or extra decoded frame")
                digest.update(block)
                count += 1
            code = process.wait(timeout=180)
            if code:
                raise ValueError(name + " full decode failed")
        finally:
            process.stdout.close()
            if process.poll() is None:
                process.kill()
                process.wait()
            process.stderr.close()
        if count != expected_frames or _sha_file(path) != before:
            raise ValueError(name + " incomplete or changed full decode")
        result[name] = {"video_sha256": before, "frames": count,
                        "rgb_sequence_sha256": digest.hexdigest(),
                        "dimensions": [width, height]}
    return {"format": "c111329-original-four-view-decode", "diagnostic": diagnostic,
            "expected_frames": expected_frames, "cameras": result,
            "auditor_sha256": hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),
            "physical_visibility": "unverified", "legal_conclusion": "not_assessed"}


def verify_media_receipt(attempt, sources, receipt_ref, expected_frames, *, diagnostic=False):
    """Check the sealed full-decode receipt against current auditor and video bytes."""
    attempt = Path(attempt).resolve()
    if not isinstance(receipt_ref, dict) or not isinstance(receipt_ref.get("path"), str):
        raise ValueError("original full-decode receipt missing")
    original = attempt / receipt_ref["path"]
    path = original.resolve()
    if not path.is_relative_to(attempt) or original.is_symlink() or not path.is_file():
        raise ValueError("original full-decode receipt escapes attempt")
    if _sha_file(path) != receipt_ref.get("sha256"):
        raise ValueError("original full-decode receipt hash mismatch")
    receipt = json.loads(path.read_text())
    if (receipt.get("format") != "c111329-original-four-view-decode" or
            receipt.get("diagnostic") != diagnostic or
            receipt.get("expected_frames") != expected_frames or
            receipt.get("auditor_sha256") != hashlib.sha256(Path(__file__).read_bytes()).hexdigest() or
            set(receipt.get("cameras", {})) != set(CAMERAS)):
        raise ValueError("original full-decode receipt stale or incomplete")
    for name in CAMERAS:
        ref = sources.get(name)
        if not isinstance(ref, dict) or not isinstance(ref.get("path"), str):
            raise ValueError(name + " original camera source missing")
        original = attempt / ref["path"]
        video = original.resolve()
        if not video.is_relative_to(attempt) or original.is_symlink() or not video.is_file():
            raise ValueError(name + " original camera source escapes attempt")
        digest = _sha_file(video)
        if (digest != ref.get("sha256") or
                receipt["cameras"][name].get("video_sha256") != digest or
                receipt["cameras"][name].get("frames") != expected_frames):
            raise ValueError(name + " original full-decode source changed")
    return receipt

"""Independent source-history audit for diagonal pedestrian comparisons."""
from __future__ import annotations

import math


def _point(value):
    if not isinstance(value, (list, tuple)) or len(value) != 2:
        raise ValueError("missing measured XY")
    xy = tuple(float(v) for v in value)
    if not all(math.isfinite(v) for v in xy):
        raise ValueError("nonfinite XY")
    return xy


def _on_segment(point, a, b):
    cross = (b[0]-a[0])*(point[1]-a[1])-(b[1]-a[1])*(point[0]-a[0])
    return abs(cross) <= 1e-7 and min(a[0], b[0]) <= point[0] <= max(a[0], b[0]) and min(a[1], b[1]) <= point[1] <= max(a[1], b[1])


def _inside(point, polygon):
    if any(_on_segment(point, a, b) for a, b in zip(polygon, polygon[1:]+polygon[:1])):
        return True
    x, y = point
    inside = False
    for a, b in zip(polygon, polygon[1:]+polygon[:1]):
        if (a[1] > y) != (b[1] > y) and x < (b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0]:
            inside = not inside
    return inside


def audit_history(plan, crossing_polygon, walker_frames, device_frames):
    """Summarize only original observed frames; reject missing synchronized sources."""
    if len(walker_frames) < 3 or len(walker_frames) != len(device_frames):
        raise ValueError("complete walker/device frame histories required")
    polygon = [_point(p) for p in crossing_polygon]
    if len(polygon) < 4:
        raise ValueError("crossing polygon required")
    indexes = [w["original_frame"] for w in walker_frames]
    if any(b != a+1 for a, b in zip(indexes, indexes[1:])):
        raise ValueError("walker frame gap")
    if [d["original_frame"] for d in device_frames] != indexes:
        raise ValueError("device/walker frame misalignment")
    walker_ids = {w.get("walker_id") for w in walker_frames}
    if len(walker_ids) != 1 or None in walker_ids:
        raise ValueError("walker identity discontinuity")
    positions = [_point(w["center_xy"]) for w in walker_frames]
    if math.dist(positions[0], _point(plan["start_xy"])) > 1.5 or math.dist(positions[-1], _point(plan["destination_xy"])) > 1.5:
        raise ValueError("opposite-corner traversal endpoints not observed")
    crossing = [i for i, p in enumerate(positions) if _inside(p, polygon)]
    if not crossing:
        raise ValueError("no observed crossing footprint")
    states = []
    for i in crossing:
        device = device_frames[i]
        if device.get("device_id") != plan["device_id"] or not device.get("source_sha256"):
            raise ValueError("governing device identity/source absent")
        if device.get("pedestrian_governance") != "diagonal":
            raise ValueError("device state not for diagonal pedestrians")
        if not device.get("instruction"):
            raise ValueError("observed diagonal instruction missing")
        states.append(device["instruction"])
    return {"walker_id": next(iter(walker_ids)), "original_frame_start": indexes[0],
            "original_frame_end": indexes[-1], "crossing_frames": [indexes[i] for i in crossing],
            "observed_instructions": states, "device_id": plan["device_id"],
            "all_crossing_frames_permissive": all(s == "diagonal_walk" for s in states),
            "source_sha256": plan["source_sha256"],
            "exception_484b_290_review": plan["exception_484b_290_review"],
            "legal_conclusion": "not_assessed"}


def audit_comparison(reference, variant):
    """Check the declared device-instruction intervention without legal labels."""
    for key in ("walker_id", "device_id", "source_sha256", "exception_484b_290_review"):
        if reference.get(key) != variant.get(key):
            raise ValueError(f"fixed comparison condition changed: {key}")
    if reference.get("crossing_frames") != variant.get("crossing_frames"):
        raise ValueError("crossing timing/geometry differs across comparison")
    if not reference.get("all_crossing_frames_permissive") or variant.get("all_crossing_frames_permissive"):
        raise ValueError("device-instruction contrast unobserved")
    return {"comparison_verified": True,
            "deliberate_difference": "observed diagonal pedestrian instruction during original crossing frames",
            "legal_conclusion": "not_assessed"}

"""Saved-only, source-sealed diagonal crossing measurement.

This consumes an actual attempt's original readbacks. It does not infer legal
compliance or turn diagnostic fixtures into physical evidence.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path

from camera_media import verify_media_receipt
from crossing_audit import audit_history
from diagonal_crossing import validate_site


ASSIGNMENT = "testing__C111329__NRS-484B-287-1e__pedestrian"
CASE_STATES = {
    ASSIGNMENT + "__permissive_whole_crossing": "permissive",
    ASSIGNMENT + "__prohibitive_whole_crossing": "prohibitive",
    ASSIGNMENT + "__instruction_changes_during_crossing": "change",
}
CAMERAS = ("overview", "approach", "reference_corner", "driver_reference")


def _sealed_json(attempt: Path, reference: dict, name: str):
    if not isinstance(reference, dict) or not isinstance(reference.get("path"), str):
        raise ValueError(f"missing {name} source reference")
    path = attempt / reference["path"]
    resolved = path.resolve()
    if not resolved.is_relative_to(attempt.resolve()) or not resolved.is_file():
        raise ValueError(f"{name} source escapes or is missing")
    digest = hashlib.sha256(resolved.read_bytes()).hexdigest()
    if digest != reference.get("sha256"):
        raise ValueError(f"{name} source hash mismatch")
    return json.loads(resolved.read_text(encoding="utf-8")), digest


def _frame_numbers(rows: list, name: str):
    if not isinstance(rows, list) or len(rows) < 3:
        raise ValueError(f"incomplete {name} history")
    frames = [row.get("original_frame") for row in rows]
    if any(type(frame) is not int for frame in frames):
        raise ValueError(f"invalid {name} frame identity")
    if any(b != a + 1 for a, b in zip(frames, frames[1:])):
        raise ValueError(f"{name} frame gap")
    return frames


def _time_join(rows: list, frames: list[int], name: str):
    for row, frame in zip(rows, frames):
        timestamp = row.get("elapsed_s")
        if not isinstance(timestamp, (int, float)) or isinstance(timestamp, bool):
            raise ValueError(f"missing {name} original timestamp")
        if abs(float(timestamp) - (frame - frames[0]) / 20.0) > 0.001:
            raise ValueError(f"{name} timestamp is not 20 Hz synchronized")


def _case_instruction(kind: str, instructions: list[str]):
    if not instructions:
        raise ValueError("no crossing instruction observed")
    allowed = {"diagonal_walk", "diagonal_dont_walk"}
    if set(instructions) - allowed:
        raise ValueError("unrecognized diagonal instruction")
    if kind == "permissive" and set(instructions) != {"diagonal_walk"}:
        raise ValueError("permissive case instruction mismatch")
    if kind == "prohibitive" and set(instructions) != {"diagonal_dont_walk"}:
        raise ValueError("prohibitive case instruction mismatch")
    if kind == "change" and not (instructions[0] == "diagonal_walk" and
                                  "diagonal_dont_walk" in instructions[1:]):
        raise ValueError("phase-change case instruction mismatch")


def process_saved(attempt_dir: str | Path, case_id: str, output: str | Path,
                  *, allow_diagnostic: bool = False):
    """Verify joins and write measured summary; raises on absent original data."""
    if case_id not in CASE_STATES:
        raise ValueError("unassigned diagonal case")
    attempt = Path(attempt_dir).resolve()
    if not attempt.is_dir():
        raise ValueError("attempt directory missing")
    manifest_path = attempt / "acquisition.json"
    if not manifest_path.is_file():
        raise ValueError("acquisition receipt missing")
    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    if manifest.get("assignment_id") != ASSIGNMENT or manifest.get("case_id") != case_id:
        raise ValueError("acquisition assignment/case mismatch")
    if manifest.get("diagnostic") is not False and not allow_diagnostic:
        raise ValueError("diagnostic or unconfirmed acquisition rejected")
    if manifest.get("fps") != 20 or manifest.get("camera_ids") != list(CAMERAS):
        raise ValueError("20 Hz four-camera acquisition contract missing")
    site, site_hash = _sealed_json(attempt, manifest.get("site"), "site")
    plan = validate_site(site, attempt)
    walker, walker_hash = _sealed_json(attempt, manifest.get("walker"), "walker")
    device, device_hash = _sealed_json(attempt, manifest.get("device"), "device")
    cameras, cameras_hash = _sealed_json(attempt, manifest.get("camera_frames"), "camera frames")
    footprint, footprint_hash = _sealed_json(attempt, manifest.get("crossing_polygon"), "crossing polygon")
    frames = _frame_numbers(walker, "walker")
    if _frame_numbers(device, "device") != frames or _frame_numbers(cameras, "camera") != frames:
        raise ValueError("source frame identities differ")
    for rows, name in ((walker, "walker"), (device, "device"), (cameras, "camera")):
        _time_join(rows, frames, name)
    device_inventory_hash = plan["source_sha256"]["device_inventory"]
    for row in device:
        if row.get("source_sha256") != device_inventory_hash:
            raise ValueError("device readback is not bound to inventoried source")
    for row in cameras:
        readings = row.get("cameras")
        if not isinstance(readings, dict) or set(readings) != set(CAMERAS):
            raise ValueError("four synchronized camera readbacks required")
        if any(type(readings[c]) is not int or readings[c] != row["original_frame"] for c in CAMERAS):
            raise ValueError("camera original-frame readback mismatch")
    measured = audit_history(plan, footprint, walker, device)
    _case_instruction(CASE_STATES[case_id], measured["observed_instructions"])
    media = manifest.get("camera_media")
    if not manifest.get("diagnostic") and not media:
        raise ValueError("original four-camera pixel media missing")
    media_receipt = (verify_media_receipt(
        attempt, media, manifest.get("camera_media_audit"), len(frames),
        diagnostic=bool(manifest.get("diagnostic"))) if media else None)
    result = {"assignment_id": ASSIGNMENT, "case_id": case_id,
              "measurement": measured, "fps": 20, "original_frames": len(frames),
              "camera_ids": list(CAMERAS), "diagnostic": bool(manifest.get("diagnostic")),
              "source_sha256": {"site": site_hash, "walker": walker_hash,
                                "device": device_hash, "camera_frames": cameras_hash,
                                "crossing_polygon": footprint_hash},
              "full_video_decode": bool(media_receipt), "actual_pixels_verified": False,
              "physical_completion_verified": False, "legal_conclusion": "not_assessed"}
    target = Path(output)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
